import json
from datetime import datetime
from urllib.parse import parse_qs, unquote

MENU = [
    {"id": "1", "name": "蛋餅", "price": 30},
    {"id": "2", "name": "培根蛋餅", "price": 40},
    {"id": "3", "name": "起司蛋餅", "price": 40},
    {"id": "4", "name": "鐵板麵", "price": 50},
    {"id": "5", "name": "火腿三明治", "price": 45},
    {"id": "6", "name": "豬肉漢堡", "price": 55},
    {"id": "7", "name": "蘿蔔糕", "price": 35},
    {"id": "8", "name": "薯餅", "price": 25},
    {"id": "9", "name": "奶茶", "price": 25},
    {"id": "10", "name": "豆漿", "price": 20},
    {"id": "11", "name": "紅茶", "price": 20},
    {"id": "12", "name": "咖啡", "price": 35},
]
MENU_BY_ID = {m["id"]: m for m in MENU}

ORDER_TYPES = ("dine_in", "takeout")
STATUSES = ("pending", "preparing", "done")

ORDERS = []
_next_id = [1]


def _err(status, message):
    return status, {"error": message}


def _parse_body(body):
    if not body:
        return None, _err(400, "請提供 JSON 內容")
    try:
        data = json.loads(body.decode("utf-8") if isinstance(body, (bytes, bytearray)) else body)
    except Exception:
        return None, _err(400, "內容不是有效的 JSON")
    if not isinstance(data, dict):
        return None, _err(400, "內容必須是 JSON 物件")
    return data, None


def _public(order):
    return {
        "id": order["id"],
        "order_type": order["order_type"],
        "table_no": order["table_no"],
        "status": order["status"],
        "total": order["total"],
        "created_at": order["created_at"],
        "lines": [dict(l) for l in order["lines"]],
    }


def _validate_order(data):
    order_type = data.get("order_type")
    if order_type not in ORDER_TYPES:
        return None, "用餐方式必須是內用 (dine_in) 或外帶 (takeout)"
    table_no = data.get("table_no", "")
    if table_no is None:
        table_no = ""
    if isinstance(table_no, bool) or not isinstance(table_no, (str, int)):
        return None, "桌號格式不正確"
    table_no = str(table_no).strip()
    if order_type == "dine_in" and not table_no:
        return None, "內用必須填寫桌號"
    raw_lines = data.get("lines")
    if not isinstance(raw_lines, list) or not raw_lines:
        return None, "訂單至少要有一項餐點"
    merged = {}
    order_ids = []
    for raw in raw_lines:
        if not isinstance(raw, dict):
            return None, "餐點項目格式不正確"
        mid = raw.get("menu_item_id")
        if isinstance(mid, bool) or not isinstance(mid, (str, int)):
            return None, "餐點編號格式不正確"
        mid = str(mid)
        if mid not in MENU_BY_ID:
            return None, "找不到餐點：" + mid
        qty = raw.get("quantity")
        if isinstance(qty, bool) or not isinstance(qty, int) or qty <= 0:
            return None, "數量必須是正整數"
        if mid not in merged:
            merged[mid] = 0
            order_ids.append(mid)
        merged[mid] += qty
    lines = []
    for mid in order_ids:
        item = MENU_BY_ID[mid]
        lines.append({
            "menu_item_id": mid,
            "name": item["name"],
            "price": item["price"],
            "quantity": merged[mid],
        })
    return {"order_type": order_type, "table_no": table_no, "lines": lines}, None


def _create_order(body):
    data, err = _parse_body(body)
    if err:
        return err
    clean, msg = _validate_order(data)
    if msg:
        return _err(400, msg)
    total = sum(l["price"] * l["quantity"] for l in clean["lines"])
    order = {
        "id": str(_next_id[0]),
        "order_type": clean["order_type"],
        "table_no": clean["table_no"],
        "status": "pending",
        "total": total,
        "created_at": datetime.now().isoformat(timespec="seconds"),
        "lines": clean["lines"],
    }
    _next_id[0] += 1
    ORDERS.append(order)
    return 201, _public(order)


def _list_orders(query):
    status = None
    vals = query.get("status")
    if vals:
        status = vals[0].strip()
    if status:
        if status not in STATUSES:
            return _err(400, "狀態必須是 pending、preparing 或 done")
        rows = [o for o in ORDERS if o["status"] == status]
    else:
        rows = list(ORDERS)
    return 200, {"items": [_public(o) for o in rows]}


def _update_status(order_id, body):
    order = None
    for o in ORDERS:
        if o["id"] == order_id:
            order = o
            break
    if order is None:
        return _err(404, "找不到這筆訂單")
    data, err = _parse_body(body)
    if err:
        return err
    status = data.get("status")
    if not isinstance(status, str) or status not in STATUSES:
        return _err(400, "狀態必須是 pending、preparing 或 done")
    order["status"] = status
    return 200, _public(order)


def _stats_today():
    today = datetime.now().date().isoformat()
    count = 0
    total = 0
    agg = {}
    for o in ORDERS:
        if not o["created_at"].startswith(today):
            continue
        count += 1
        total += o["total"]
        for l in o["lines"]:
            e = agg.setdefault(l["menu_item_id"], {
                "menu_item_id": l["menu_item_id"],
                "name": l["name"],
                "quantity": 0,
                "amount": 0,
            })
            e["quantity"] += l["quantity"]
            e["amount"] += l["price"] * l["quantity"]
    ranked = sorted(
        agg.values(),
        key=lambda e: (-e["quantity"], -e["amount"], int(e["menu_item_id"])),
    )
    return 200, {
        "date": today,
        "order_count": count,
        "total_amount": total,
        "top_items": ranked[:3],
    }


def handle(method, path, body):
    method = (method or "").upper()
    path = path or "/"
    query = {}
    if "?" in path:
        path, qs = path.split("?", 1)
        query = parse_qs(qs)
    if not path.startswith("/"):
        path = "/" + path
    if path.startswith("/api/"):
        path = path[4:]
    if len(path) > 1:
        path = path.rstrip("/")
    if not path:
        path = "/"

    if path == "/menu":
        if method != "GET":
            return _err(405, "不支援此方法")
        return 200, {"items": [dict(m) for m in MENU]}

    if path == "/orders":
        if method == "GET":
            return _list_orders(query)
        if method == "POST":
            return _create_order(body)
        return _err(405, "不支援此方法")

    parts = path.split("/")
    if len(parts) == 4 and parts[1] == "orders" and parts[3] == "status" and parts[2]:
        if method != "PATCH":
            return _err(405, "不支援此方法")
        return _update_status(unquote(parts[2]), body)

    if path == "/stats/today":
        if method != "GET":
            return _err(405, "不支援此方法")
        return _stats_today()

    return _err(404, "找不到此路徑")

