(function () {
  'use strict';

  var STATUS_LABELS = { pending: '待做', preparing: '製作中', done: '完成' };
  var TYPE_LABELS = { dine_in: '內用', takeout: '外帶' };
  var STATUS_ORDER = ['pending', 'preparing', 'done'];

  var menu = [];
  var cart = {}; // menu item id -> quantity
  var currentTab = 'order';
  var kitchenTimer = null;

  function $(id) { return document.getElementById(id); }

  function el(tag, className, text) {
    var e = document.createElement(tag);
    if (className) e.className = className;
    if (text !== undefined && text !== null) e.textContent = text;
    return e;
  }

  function clear(node) {
    while (node.firstChild) node.removeChild(node.firstChild);
  }

  function showMessage(node, text, kind) {
    if (!text) {
      node.hidden = true;
      node.textContent = '';
      return;
    }
    node.className = 'message ' + (kind || 'error');
    node.textContent = text;
    node.hidden = false;
  }

  // Unified API caller
  function api(method, path, body) {
    var opts = { method: method, headers: {} };
    if (body !== undefined) {
      opts.headers['Content-Type'] = 'application/json';
      opts.body = JSON.stringify(body);
    }
    return fetch('api/' + path, opts).then(function (res) {
      return res.text().then(function (text) {
        var data = null;
        if (text) {
          try { data = JSON.parse(text); } catch (e) { data = null; }
        }
        if (!res.ok) {
          var msg = data && data.error ? String(data.error) : ('請求失敗（狀態碼 ' + res.status + '）');
          throw new Error(msg);
        }
        if (data === null || typeof data !== 'object') {
          throw new Error('伺服器回應格式不正確');
        }
        return data;
      });
    }, function () {
      throw new Error('無法連線到伺服器，請稍後再試');
    });
  }

  function money(n) {
    var v = Number(n);
    return isNaN(v) ? String(n) : String(v);
  }

  function formatTime(s) {
    if (!s) return '';
    return String(s).replace('T', ' ');
  }

  // ---------- Tabs ----------
  function switchTab(name) {
    currentTab = name;
    var tabs = document.querySelectorAll('.tab');
    for (var i = 0; i < tabs.length; i++) {
      tabs[i].classList.toggle('active', tabs[i].getAttribute('data-tab') === name);
    }
    $('tab-order').hidden = name !== 'order';
    $('tab-kitchen').hidden = name !== 'kitchen';
    $('tab-stats').hidden = name !== 'stats';
    if (kitchenTimer) { clearInterval(kitchenTimer); kitchenTimer = null; }
    if (name === 'order') {
      loadMenu();
    } else if (name === 'kitchen') {
      loadOrders();
      kitchenTimer = setInterval(loadOrders, 10000);
    } else if (name === 'stats') {
      loadStats();
    }
  }

  // ---------- Order tab ----------
  function loadMenu() {
    api('GET', 'menu').then(function (data) {
      menu = Array.isArray(data.items) ? data.items : [];
      showMessage($('global-error'), '');
      renderMenu();
      renderCart();
    }).catch(function (err) {
      showMessage($('global-error'), '無法載入菜單：' + err.message, 'error');
    });
  }

  function renderMenu() {
    var box = $('menu-list');
    clear(box);
    if (!menu.length) {
      box.appendChild(el('p', 'empty', '目前沒有可點的餐點'));
      return;
    }
    menu.forEach(function (item) {
      var id = String(item.id);
      var row = el('div', 'menu-item');
      var info = el('div', 'menu-info');
      info.appendChild(el('span', 'menu-name', item.name));
      info.appendChild(el('span', 'menu-price', money(item.price) + ' 元'));
      row.appendChild(info);
      var ctl = el('div', 'qty-ctl');
      var minus = el('button', 'qty-btn', '－');
      minus.type = 'button';
      minus.setAttribute('data-action', 'dec');
      minus.setAttribute('data-id', id);
      minus.setAttribute('aria-label', '減少 ' + item.name);
      var qty = el('span', 'qty', String(cart[id] || 0));
      var plus = el('button', 'qty-btn', '＋');
      plus.type = 'button';
      plus.setAttribute('data-action', 'inc');
      plus.setAttribute('data-id', id);
      plus.setAttribute('aria-label', '增加 ' + item.name);
      ctl.appendChild(minus);
      ctl.appendChild(qty);
      ctl.appendChild(plus);
      row.appendChild(ctl);
      box.appendChild(row);
    });
  }

  function findMenu(id) {
    for (var i = 0; i < menu.length; i++) {
      if (String(menu[i].id) === id) return menu[i];
    }
    return null;
  }

  function renderCart() {
    var box = $('cart-list');
    clear(box);
    var total = 0;
    var count = 0;
    menu.forEach(function (item) {
      var id = String(item.id);
      var q = cart[id] || 0;
      if (q > 0) {
        count++;
        var sub = Number(item.price) * q;
        total += sub;
        var row = el('div', 'cart-row');
        row.appendChild(el('span', 'cart-name', item.name));
        row.appendChild(el('span', 'cart-qty', '× ' + q));
        row.appendChild(el('span', 'cart-sub', sub + ' 元'));
        box.appendChild(row);
      }
    });
    if (!count) box.appendChild(el('p', 'empty', '尚未選擇餐點'));
    $('cart-total').textContent = String(total);
  }

  function onMenuClick(ev) {
    var t = ev.target;
    if (!t || !t.getAttribute) return;
    var action = t.getAttribute('data-action');
    if (!action) return;
    var id = t.getAttribute('data-id');
    var cur = cart[id] || 0;
    if (action === 'inc') cur += 1;
    else if (action === 'dec' && cur > 0) cur -= 1;
    if (cur > 0) cart[id] = cur; else delete cart[id];
    renderMenu();
    renderCart();
  }

  function selectedType() {
    var radios = document.getElementsByName('order_type');
    for (var i = 0; i < radios.length; i++) {
      if (radios[i].checked) return radios[i].value;
    }
    return 'dine_in';
  }

  function updateTableRow() {
    $('table-row').hidden = selectedType() !== 'dine_in';
  }

  function submitOrder(ev) {
    ev.preventDefault();
    var result = $('order-result');
    var type = selectedType();
    var tableNo = type === 'dine_in' ? $('table-no').value.trim() : '';
    var lines = [];
    Object.keys(cart).forEach(function (id) {
      if (cart[id] > 0) lines.push({ menu_item_id: id, quantity: cart[id] });
    });
    if (!lines.length) {
      showMessage(result, '請至少選擇一項餐點', 'error');
      return;
    }
    if (type === 'dine_in' && !tableNo) {
      showMessage(result, '內用請填寫桌號', 'error');
      return;
    }
    var btn = $('submit-btn');
    btn.disabled = true;
    api('POST', 'orders', { order_type: type, table_no: tableNo, lines: lines }).then(function (order) {
      var text = '訂單已送出！編號 ' + order.id + '，' + (TYPE_LABELS[order.order_type] || order.order_type);
      if (order.table_no) text += '，桌號 ' + order.table_no;
      text += '，總金額 ' + money(order.total) + ' 元';
      showMessage(result, text, 'success');
      cart = {};
      $('table-no').value = '';
      renderMenu();
      renderCart();
    }).catch(function (err) {
      showMessage(result, '送出失敗：' + err.message, 'error');
    }).then(function () {
      btn.disabled = false;
    });
  }

  // ---------- Kitchen tab ----------
  function loadOrders() {
    api('GET', 'orders').then(function (data) {
      var items = Array.isArray(data.items) ? data.items : [];
      showMessage($('kitchen-error'), '');
      renderOrders(items);
    }).catch(function (err) {
      showMessage($('kitchen-error'), '無法載入訂單：' + err.message, 'error');
    });
  }

  function renderOrders(items) {
    var filter = $('status-filter').value;
    var box = $('orders-list');
    clear(box);
    var shown = items.filter(function (o) { return !filter || o.status === filter; });
    if (!shown.length) {
      box.appendChild(el('p', 'empty', filter ? '沒有符合狀態的訂單' : '尚無訂單'));
      return;
    }
    shown.forEach(function (o) {
      var card = el('div', 'order-card status-' + o.status);
      var head = el('div', 'order-head');
      var title = '#' + o.id + ' ' + (TYPE_LABELS[o.order_type] || o.order_type);
      if (o.table_no) title += '（桌號 ' + o.table_no + '）';
      head.appendChild(el('strong', null, title));
      head.appendChild(el('span', 'badge', STATUS_LABELS[o.status] || o.status));
      card.appendChild(head);
      card.appendChild(el('div', 'order-time', formatTime(o.created_at)));
      var ul = el('ul', 'order-lines');
      (o.lines || []).forEach(function (l) {
        ul.appendChild(el('li', null, l.name + ' × ' + l.quantity + '（' + money(l.price) + ' 元）'));
      });
      card.appendChild(ul);
      card.appendChild(el('div', 'order-total', '總計：' + money(o.total) + ' 元'));
      var actions = el('div', 'order-actions');
      STATUS_ORDER.forEach(function (s) {
        var b = el('button', 'status-btn' + (o.status === s ? ' current' : ''), STATUS_LABELS[s]);
        b.type = 'button';
        b.setAttribute('data-order-id', String(o.id));
        b.setAttribute('data-status', s);
        if (o.status === s) b.disabled = true;
        actions.appendChild(b);
      });
      card.appendChild(actions);
      box.appendChild(card);
    });
  }

  function onOrdersClick(ev) {
    var t = ev.target;
    if (!t || !t.getAttribute) return;
    var status = t.getAttribute('data-status');
    var id = t.getAttribute('data-order-id');
    if (!status || !id) return;
    t.disabled = true;
    api('PATCH', 'orders/' + encodeURIComponent(id) + '/status', { status: status }).then(function () {
      showMessage($('kitchen-error'), '');
      loadOrders();
    }).catch(function (err) {
      showMessage($('kitchen-error'), '更新狀態失敗：' + err.message, 'error');
      loadOrders();
    });
  }

  // ---------- Stats tab ----------
  function loadStats() {
    api('GET', 'stats/today').then(function (data) {
      showMessage($('stats-error'), '');
      renderStats(data);
    }).catch(function (err) {
      showMessage($('stats-error'), '無法載入營業額：' + err.message, 'error');
    });
  }

  function renderStats(d) {
    var box = $('stats-content');
    clear(box);
    if (d.date) box.appendChild(el('p', 'stats-date', '日期：' + d.date));
    var cards = el('div', 'stats-cards');
    var c1 = el('div', 'stat-card');
    c1.appendChild(el('div', 'stat-label', '訂單數'));
    c1.appendChild(el('div', 'stat-value', String(d.order_count)));
    var c2 = el('div', 'stat-card');
    c2.appendChild(el('div', 'stat-label', '總金額'));
    c2.appendChild(el('div', 'stat-value', money(d.total_amount) + ' 元'));
    cards.appendChild(c1);
    cards.appendChild(c2);
    box.appendChild(cards);
    box.appendChild(el('h3', null, '熱賣前三名'));
    var tops = Array.isArray(d.top_items) ? d.top_items : [];
    if (!tops.length) {
      box.appendChild(el('p', 'empty', '今天還沒有銷售紀錄'));
      return;
    }
    var ol = el('ol', 'top-list');
    tops.forEach(function (it) {
      ol.appendChild(el('li', null, it.name + '：' + it.quantity + ' 份，' + money(it.amount) + ' 元'));
    });
    box.appendChild(ol);
  }

  // ---------- Init ----------
  function init() {
    var tabs = document.querySelectorAll('.tab');
    for (var i = 0; i < tabs.length; i++) {
      tabs[i].addEventListener('click', function (ev) {
        switchTab(ev.currentTarget.getAttribute('data-tab'));
      });
    }
    $('menu-list').addEventListener('click', onMenuClick);
    var radios = document.getElementsByName('order_type');
    for (var j = 0; j < radios.length; j++) {
      radios[j].addEventListener('change', updateTableRow);
    }
    $('order-form').addEventListener('submit', submitOrder);
    $('orders-list').addEventListener('click', onOrdersClick);
    $('status-filter').addEventListener('change', loadOrders);
    $('kitchen-refresh').addEventListener('click', loadOrders);
    $('stats-refresh').addEventListener('click', loadStats);
    updateTableRow();
    switchTab('order');
  }

  document.addEventListener('DOMContentLoaded', init);
})();

